  static bool ToolContactAllowed(Piece p){
   string contact=UniqueContact(p);if(contact==null)return false;
   if(ActualAttached(p.Part))return Object.ReferenceEquals(held,p)&&p.LastContact==contact;
   if(AnyAttached(p.Part))return false;
   if(p.Support=="Source")return contact=="C1"&&At(p.Part,p.Spawn);
   if(p.Support=="Fixture")return At(p.Part,fixture)&&(contact=="C2"||(p.ReleasedContactPending&&p.LastContact=="C1"&&contact=="C1"));
   return p.Support.StartsWith("Box:")&&p.ReleasedContactPending&&p.LastContact=="C2"&&contact=="C2"&&At(p.Part,SupportPose(p,p.Support));
  }
  static bool SupportContactAllowed(Piece p,string obstacle){
   // Walls, conveyor frame and physical Floor are never allowable support contacts.
   if(obstacle=="ConveyorSurface")return (p.Support=="Source"||Object.ReferenceEquals(p,held)&&p.LastContact=="C1")&&At(p.Part,p.Spawn);
   if(obstacle=="InterimFixture")return (p.Support=="Fixture"||Object.ReferenceEquals(p,held))&&At(p.Part,fixture);
   if(obstacle=="PackingBoxFloor")return (p.Support.StartsWith("Box:")||Object.ReferenceEquals(p,held)&&p.LastContact=="C2")&&boxSlots.Any(b=>At(p.Part,b));
   return false;
  }
