  public static bool CheckNow(double simulationTimeMs){CheckUi();if(!installed)return false;if(CollisionStopRequested)return false;if(!IsActive){Fail("Monitor ownership/settings changed.");return false;}if(checking)return !CollisionStopRequested;checking=true;
